CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, summary TEXT NOT NULL DEFAULT '',model_override TEXT NOT NULL DEFAULT 'auto');
 CREATE TABLE IF NOT EXISTS updates(id INTEGER PRIMARY KEY, payload TEXT NOT NULL, dispatched INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),role TEXT NOT NULL,content TEXT NOT NULL,created INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),instruction TEXT NOT NULL,status TEXT NOT NULL,session TEXT NOT NULL DEFAULT '',tier TEXT NOT NULL DEFAULT '',model TEXT NOT NULL DEFAULT '',reasoning TEXT NOT NULL DEFAULT '',override TEXT NOT NULL DEFAULT 'auto',summary TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 0,retry_after INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS instructions(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id TEXT NOT NULL REFERENCES tasks(id),content TEXT NOT NULL,applied INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),number INTEGER NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL,offset INTEGER NOT NULL DEFAULT 0,tier TEXT NOT NULL DEFAULT '',error_class TEXT NOT NULL DEFAULT '',finished INTEGER,exit_code INTEGER,UNIQUE(task_id,number));
 CREATE UNIQUE INDEX IF NOT EXISTS one_execution ON attempts((1)) WHERE status IN ('claimed','running');
 CREATE TABLE IF NOT EXISTS events(attempt_id TEXT NOT NULL REFERENCES attempts(id),offset INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(attempt_id,offset));
 CREATE TABLE IF NOT EXISTS model_selections(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),tier TEXT NOT NULL,model TEXT NOT NULL,reasoning TEXT NOT NULL,source TEXT NOT NULL,confidence REAL,created INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),instruction_version INTEGER NOT NULL,action TEXT NOT NULL,response TEXT,created INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,content TEXT NOT NULL,task_id TEXT NOT NULL DEFAULT '',delivered INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,retry_after INTEGER NOT NULL DEFAULT 0);
 INSERT OR IGNORE INTO schema_migrations VALUES(1);
